import {createGym4JourneyScenePreparer} from '../gohyeon-gym4/prepare-scenes.mjs';
import {createS4DistanceCenterScene as createCenterInteriorScene} from '../gohyeon-gameplay/encounter/movement-proof.mjs';
import {createGohyeonHealBinding} from '../../world/gohyeon-heal-binding.mjs';
export function createCenterJourneyScenePreparer({centerInputs,...options}){const base=createGym4JourneyScenePreparer(options);let epoch=0;return async location=>{if(options.registry.validate(location))throw Error('FIXED_CENTER_LOCATION_INVALID');if(location.servicePose){const scene=await createCenterInteriorScene({safe:centerInputs.safe,retainedExterior:location,epoch:++epoch,assets:{...centerInputs.assets,playerFrames:options.playerActors},layout:centerInputs.layout});scene.proximityHint=()=>scene.counterIntent()?'의사에게 회복 요청 · 위를 보고 조사':scene.isReturnTrigger()?'회복센터 출입구 · 아래를 보고 조사':'회복센터 · 카운터까지 걸어가세요';return scene}const scene=await base(location);if(scene.mapId!=='world:hub:S4')return scene;const original=scene.inspect.bind(scene),hint=scene.proximityHint?.bind(scene),canEnter=()=>{if(scene.getLocation().indoorPose)return false;const binding=createGohyeonHealBinding({getWorld:()=>scene.world,getScene:()=>scene.scene});try{return binding.canHeal()}finally{binding.dispose()}};scene.proximityHint=()=>canEnter()?'회복센터 · 조사하여 입장':hint?.();scene.inspect=execution=>canEnter()?execution('service:center:enter'):original(execution);return scene}}
